// Package bpf — stub types for the ProcTable BPF program.
//
// The real ProcTableObjects / LoadProcTableObjects / LoadProcTable are generated by
// `make generate` (bpf2go compiles bpf/proctable.bpf.c and emits Go bindings). This stub
// provides the same exported API so packages that import internal/bpf can be compiled and
// tested without a clang/kernel-headers toolchain — notably on macOS, where clang has no BPF
// backend at all.
//
// In a production build, run `make generate` first; the generated
// proctable_bpfel.go / proctable_bpfeb.go files replace this stub, which
// `make generate` deletes.

package bpf

import (
	"errors"
	"fmt"

	"github.com/cilium/ebpf"
)

// ProcTableMaps holds the BPF maps exported by bpf/proctable.bpf.c.
type ProcTableMaps struct {
	ProcLive          *ebpf.Map `ebpf:"proc_live"`
	ProcExited        *ebpf.Map `ebpf:"proc_exited"`
	ProcTableCounters *ebpf.Map `ebpf:"proc_table_counters"`
}

// ProcTablePrograms holds the BPF programs exported by bpf/proctable.bpf.c.
type ProcTablePrograms struct {
	ProcFork *ebpf.Program `ebpf:"proc_fork"`
	ProcExec *ebpf.Program `ebpf:"proc_exec"`
	ProcExit *ebpf.Program `ebpf:"proc_exit"`
}

// ProcTableObjects contains all BPF objects after loading bpf/proctable.bpf.c.
type ProcTableObjects struct {
	ProcTablePrograms
	ProcTableMaps
}

// Close releases all BPF resources held by the objects.
func (o *ProcTableObjects) Close() error {
	var errs []error
	for _, p := range []*ebpf.Program{o.ProcFork, o.ProcExec, o.ProcExit} {
		if p != nil {
			errs = append(errs, p.Close())
		}
	}
	for _, m := range []*ebpf.Map{o.ProcLive, o.ProcExited, o.ProcTableCounters} {
		if m != nil {
			errs = append(errs, m.Close())
		}
	}
	return errors.Join(errs...)
}

// LoadProcTable returns the embedded collection spec. This stub always returns an error —
// run `make generate` to produce the real implementation from bpf/proctable.bpf.c.
func LoadProcTable() (*ebpf.CollectionSpec, error) {
	return nil, fmt.Errorf("bpf: ProcTable program not available (run make generate to compile BPF programs)")
}
